def apply_voice(lang,slug,body,items,label_index):
 import re
 from html import escape
 c=CORE[lang];f=FACTS[lang]
 if slug=='products':
  body=re.sub(r'(<section class="page-intro">.*?</h1>)<p>.*?</p>',lambda m:m[1]+'<p>'+escape(OVERVIEW[lang])+'</p>',body,count=1,flags=re.S)
 if slug.startswith('collections/'):
  tail=slug.split('/')[-1];index=next((i for i,it in enumerate(items) if it[0]==tail),None)
  if index is not None:
   lead,heading,p1,p2=PRODUCTS[lang][index]
   body=re.sub(r'(<section class="split-intro">.*?<h1>.*?</h1>)<p>.*?</p>',lambda m:m[1]+'<p>'+escape(lead)+'</p>',body,count=1,flags=re.S)
   body=re.sub(r'(<section class="section product-detail"><div>).*?(</div><aside>)',lambda m:m[1]+'<span class="eyebrow">'+escape(c['product_heading'])+'</span><h2>'+escape(heading)+'</h2><p>'+escape(p1)+'</p><p>'+escape(p2)+'</p>'+m[2],body,count=1,flags=re.S)
  else:
   group=next((it[1] for it in items if ['home-textiles','hotel-spa-textiles','baby-textiles'][it[1]]==tail),None)
   if group is not None:
    body=re.sub(r'(<section class="split-intro">.*?<h1>.*?</h1>)<p>.*?</p>',lambda m:m[1]+'<p>'+escape(GROUPS[lang][group])+'</p>',body,count=1,flags=re.S)
 if slug=='about':
  body=re.sub(r'(<section class="page-intro">.*?<h1>).*?(</h1>)',lambda m:m[1]+f['about_heading']+m[2],body,count=1,flags=re.S)
  body=re.sub(r'(<section class="page-intro">.*?</h1>)<p>.*?</p>',lambda m:m[1]+'<p>'+escape(f['about'])+'</p><p>'+escape(c['about_more'])+'</p>',body,count=1,flags=re.S)
  market=f'<section class="section company-facts"><div><span class="eyebrow">TVS TEXTILE / {FOUNDED}</span><h2>{escape(f["factory"])}</h2><p>{escape(f["year"])}</p></div><div><h3>{escape(f["market_heading"])}</h3><p>{escape(f["markets"])}</p></div></section>'
  body=body.replace('<section class="project-section">',market+'<section class="project-section">',1)
 if slug=='index':
  body=re.sub(r'(<div class="story-copy reveal">.*?</h2>)<p>.*?</p>',lambda m:m[1]+'<p>'+escape(f['about'])+'</p>',body,count=1,flags=re.S)
  badge='<div class="factory-note"><span>'+escape(f['factory'])+'</span><span>'+escape(f['year'])+'</span></div>'
  body=body.replace('<div class="hero-foot">',badge+'<div class="hero-foot">',1)
  steps={
   'en': [('We start with the product','We want to understand the fabric, size and details that will shape your collection.'),('We discuss what remains open','We ask which sample and specification questions you want to resolve before ordering.'),('We clarify the next step','We want the quotation, agreed details and destination to be clear before an order is placed.')],
   'fr': [('Nous partons du produit','Nous souhaitons comprendre les matières, mesures et détails de votre collection.'),('Nous discutons des choix ouverts','Nous demandons quels points de spécification et d’échantillonnage restent à préciser.'),('Nous clarifions la suite','Nous voulons un devis, des détails convenus et une destination clairement définis avant la commande.')],
   'de': [('Wir beginnen beim Produkt','Wir möchten Material, Maße und die Details Ihrer Kollektion verstehen.'),('Wir besprechen offene Fragen','Wir fragen nach den Muster- und Spezifikationspunkten, die noch zu klären sind.'),('Wir klären den nächsten Schritt','Wir möchten Angebot, vereinbarte Details und Zielland vor der Bestellung festhalten.')],
   'es': [('Empezamos por el producto','Queremos entender materiales, medidas y detalles de su colección.'),('Comentamos las decisiones abiertas','Preguntamos qué puntos de muestras y especificaciones quiere concretar.'),('Aclaramos el siguiente paso','Queremos presupuesto, detalles acordados y destino claros antes de un pedido.')]
  }
  rows=iter(steps[lang])
  body=re.sub(r'(<div class="brief-card reveal"><span>.*?</span>)<h3>.*?</h3><p>.*?</p>',lambda m:step_row(m,next(rows)),body,flags=re.S)
 if slug=='sourcing-guide':
  matches=iter(GUIDE[lang])
  body=re.sub(r'(<article class="guide-row reveal"><span>.*?</span><div>)<h2>.*?</h2><p>.*?</p>(</div></article>)',lambda m:guide_row(m,next(matches)),body,flags=re.S)
 if slug=='privacy':
  body=body.replace('so TVS Textile can respond','so we can respond').replace('Contact data</h1>','Contact data</h1>')
 return body

def guide_row(match,copy):
 from html import escape
 return match[1]+'<h2>'+escape(copy[0])+'</h2><p>'+escape(copy[1])+'</p>'+match[2]

def step_row(match,copy):
 from html import escape
 return match[1]+'<h3>'+escape(copy[0])+'</h3><p>'+escape(copy[1])+'</p>'
